function showSignup(signup){$('#loginForm').hidden=signup;$('#signupForm').hidden=!signup;$('#signupResult').hidden=true;$('#authTitle').textContent=signup?'Yeni hesap oluştur':'Hesabına giriş yap';$('#authError').textContent=''}
function error(msg){$('#authError').textContent=msg||'Bir hata oluştu.'}
async function login(){let btn=$('#loginBtn');btn.disabled=true;error('');try{let username=$('#loginUsername').value.trim(),magic=$('#loginMagic').value.trim(),code=$('#loginCode').value.trim();if(!username||!magic||!/^[0-9]{6}$/.test(code))throw Error('Kullanıcı adı, sihirli ifade ve 6 haneli kod gerekli.');await c.login(username,magic,code,$('#loginRemember').checked);showWorkspace()}catch(e){error(e.message)}finally{btn.disabled=false}}
// Registration credentials must remain visible until the student explicitly confirms they saved them.
async function signup(){let btn=$('#signupBtn');btn.disabled=true;error('');try{let code=$('#signupCode').value.trim();if(!/^\d{6}$/.test(code)||code!==$('#signupCodeConfirm').value.trim())throw Error('6 haneli kodlar eşleşmelidir.');let result=await c.createAccount(code,$('#signupRemember').checked);$('#signupForm').hidden=true;$('#authTitle').textContent='Hesabın oluşturuldu';$('#signupResult').hidden=false;$('#signupResult').innerHTML=`<p>Üç giriş bilgisini güvenli bir yere kaydet. Sihirli ifade daha sonra tekrar gösterilmez; gerektiğinde yönetici hesabı sıfırlayabilir.</p><div class="cred"><small>Kullanıcı adı</small><strong>${esc(result.username)}</strong></div><div class="cred"><small>Sihirli ifade</small><strong>${esc(result.magicWord)}</strong></div><div class="cred"><small>Erişim kodun</small><strong>${esc(result.accessCode)}</strong></div><label class="checkline"><input type="checkbox" id="credentialSaved"> Bu üç bilgiyi kaydettim</label><button class="primary-btn full" id="finishSignup" disabled>Kaydettim, devam et</button>`;$('#credentialSaved').addEventListener('change',e=>$('#finishSignup').disabled=!e.target.checked);$('#finishSignup').addEventListener('click',async()=>{try{await c.finishSignup();showWorkspace()}catch(e){error(e.message)}})}catch(e){error(e.message)}finally{btn.disabled=false}}
function ensureSelection(){let s=state(),all=m.courses(s);if(!all.some(x=>x.id===courseId))courseId=all[0]?.id||null;let resources=m.resources(s,courseId);if(!resources.some(x=>x.id===resourceId))resourceId=resources[0]?.id||null;let allWeeks=m.weeks(s.settings.start,s.settings.end);if(!allWeeks.includes(selectedWeek))selectedWeek=allWeeks.includes(curWeek())?curWeek():allWeeks[0]}
function go(p){page=p;$('#sidebar').classList.remove('open');render()}
function render(){if(!c.account)return;ensureSelection();$$('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));$$('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));let title={home:'Genel Bakış',courses:'Derslerim',weekly:'Haftalık Plan',resources:'Kaynaklar',analytics:'İstatistikler',settings:'Ayarlar & bağlantılar'};$('#breadcrumb').textContent=title[page]||'';renderSidebar();renderCourses();renderWeekly();renderResources();renderHome();renderAnalytics();renderSettings()}
function renderSidebar(){let s=state();$('#sideCourses').innerHTML=m.courses(s).map(x=>`<button data-open-course="${x.id}" class="${page==='courses'&&courseId===x.id?'active':''}"><i class="course-dot" style="--course-color:${esc(x.color||'#159e89')}"></i>${esc(x.name)}</button>`).join('');let w=m.weekStats(s,curWeek());$('#sideWeekText').textContent=`${w.done} / ${w.total} konu tamamlandı`;$('#sideWeekBar').style.width=w.pct+'%'}
function renderCourses(){let s=state(),cs=m.courses(s);$('#courseTabs').innerHTML=cs.map(x=>{let st=m.courseStats(s,x.id);return `<button class="course-tab ${courseId===x.id?'active':''}" data-open-course="${x.id}">${esc(x.name)} <span class="pct">${st.pct}%</span></button>`}).join('')+'<button class="course-tab add" data-action="add-course">＋ Yeni ders</button><button class="course-tab" data-action="show-archive">Arşiv ↗</button>';let current=course(courseId);$('#courseTitle').textContent=current?.name||'Henüz ders eklenmedi';let stat=current?m.courseStats(s,current.id):{pct:0,done:0,total:0};$('#coursePill').textContent=stat.pct+'% tamamlandı';$('#courseNote').textContent=stat.done+' / '+stat.total+' bağımsız takip konusu';$('#resourceMapTabs').innerHTML=m.resources(s,courseId).map(r=>{let t=m.resourceStats(s,r.id);return `<button data-open-resource="${r.id}" class="resource-map-tab ${resourceId===r.id?'active':''}"><span>▤</span><span><strong>${esc(r.title)}</strong><small>${t.done}/${t.total} içerik</small></span><span class="source-pct">${t.pct}%</span></button>`}).join('');$('#showWeekPlans').checked=showWeeks;$('#mapGroupMode').checked=mapGroupMode;let available=m.weeks(s.settings.start,s.settings.end);$('#bulkWeekTarget').innerHTML=available.map(w=>`<option value="${w}">${esc(range(w))}</option>`).join('');$('#bulkWeekTarget').value=available.includes(selectedWeek)?selectedWeek:available[0];$('#bulkAssignBar').classList.toggle('visible',planMode);$('#toggleWeekAssign').classList.toggle('active',planMode);$('#bulkSelectedCount').textContent=selection.size+' konu seçildi';let r=resource(resourceId);if(!r){$('#unitsGrid').innerHTML='<div class="empty-hint">Bu derse kaynak ekleyerek içerik haritası oluşturabilirsin.</div>';return}let top=m.children(s,null,r.id);if(!top.length){$('#unitsGrid').innerHTML='<div class="empty-hint">Bu kaynağın konu haritası boş. AI JSON içe aktarabilir veya bölüm ekleyebilirsin. <button class="primary-btn" data-action="import-resource">AI ile harita oluştur</button></div>';return}$('#unitsGrid').innerHTML=top.map((root,i)=>renderUnit(root,i)).join('')}
function descendantLeaves(root){let s=state(),all=m.nodes(s,root.resourceId),parents=new Map();for(let n of all){if(!parents.has(n.parentId))parents.set(n.parentId,[]);parents.get(n.parentId).push(n)}let out=[];function walk(n,path,seen){if(seen.has(n.id))return;seen.add(n.id);let kids=parents.get(n.id)||[];if(!kids.length){out.push({node:n,path:path.join(' › ')})}else for(let child of kids.sort((a,b)=>a.sortOrder-b.sortOrder))walk(child,[...path,child.title],seen)}walk(root,[root.title],new Set());return out}
function renderUnit(root,index){
 let s=state(),all=descendantLeaves(root),stats=m.stats(s,all.map(x=>x.node)),assignments=m.liveAssignments(s);
 const marker=n=>{let status=m.status(s,n.id),week=assignments.find(a=>a.nodeId===n.id)?.weekStartDate||'',planned=showWeeks&&week;
 return `<div class="map-item ${planned?'week-planned':''}" style="${planned?'--week-color:#159e89':''}"><button data-node-click="${n.id}" title="${esc(n.title)}" class="node ${esc(n.type||'topic')} ${status==='completed'?'completed':status==='progress'?'progress':''} ${selection.has(n.id)?'selected':''}" aria-label="${esc(n.title)}">${mark(n.type)}</button>${week?`<span class="map-week-badge">${labelDate(week)}</span>`:''}</div>`};
 let listed=all.filter(x=>!filterCompleted||m.status(s,x.node.id)!=='completed');
 let content='';
 if(view==='grid'&&mapGroupMode){
  const visibleNodes=new Set(listed.map(x=>x.node.id));
  function group(n,depth,seen){if(seen.has(n.id))return '';let next=new Set([...seen,n.id]),kids=m.children(s,n.id,n.resourceId),showLeaf=visibleNodes.has(n.id);
   if(!kids.length)return showLeaf?marker(n):'';
   let body=kids.map(c=>group(c,depth+1,next)).join('');if(!body)return '';
   if(n.id===root.id)return body;
   return `<section class="topic-subgroup" style="--group-depth:${Math.min(depth,8)}"><h4 class="topic-subgroup-title">${esc(n.title)}</h4><div class="topic-subgroup-content">${body}</div></section>`;
  }
  content=`<div class="unit-grouped-map ${showWeeks?'show-week-plans':''}">${group(root,0,new Set())||'<span class="muted-text">Gösterilecek konu yok.</span>'}</div>`;
 }else if(view==='grid')content=`<div class="unit-dots ${showWeeks?'show-week-plans':''}">${listed.map(x=>marker(x.node)).join('')||'<span class="muted-text">Gösterilecek konu yok.</span>'}</div>`;
 else content=`<div class="unit-list ${showWeeks?'show-week-plans':''}">${listed.map(({node:n,path})=>{let status=m.status(s,n.id);return `<div class="node-row"> <button data-node-click="${n.id}" title="${esc(n.title)}" class="node ${esc(n.type||'topic')} ${status==='completed'?'completed':status==='progress'?'progress':''}" aria-label="${esc(n.title)}">${mark(n.type)}</button><span class="node-label" title="${esc(path)}">${esc(path)}</span></div>`}).join('')||'<span class="muted-text">Gösterilecek konu yok.</span>'}</div>`;
 return `<article class="unit-card"><div class="unit-head"><div class="unit-title-wrap"><div class="unit-num">${index+1}</div><div><div class="unit-title">${esc(root.title)}</div><div class="unit-meta">${stats.done}/${stats.total} konu tamamlandı</div></div></div><div class="unit-actions"><span class="unit-percent">${stats.pct}%</span></div></div>${content}</article>`;
}
function renderResources(){let s=state(),selected=$('#resourceFilter').value||'all';$('#resourceFilter').innerHTML='<option value="all">Tüm dersler</option>'+m.courses(s).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('#resourceFilter').value=selected;$('#allResourcesGrid').innerHTML=m.resources(s).filter(x=>selected==='all'||x.courseId===selected).map(r=>{let st=m.resourceStats(s,r.id);return `<article class="resource-card"><div class="resource-icon">▤</div><h3>${esc(r.title)}</h3><p>${esc(courseName(r.courseId))} · ${esc(r.type)}</p><div class="resource-foot"><span>${st.done}/${st.total} konu</span><span>${st.pct}%</span></div><div class="open-map"><button class="tiny-btn" data-open-resource="${r.id}">Haritayı aç</button><button class="tiny-btn" data-action="outline-editor" data-id="${r.id}">İçindekileri düzenle</button><details class="resource-more"><summary aria-label="Diğer kaynak seçenekleri">•••</summary><div><button class="tiny-btn" data-action="edit-resource" data-id="${r.id}">Kaynak bilgileri</button><button class="tiny-btn" data-action="archive-resource" data-id="${r.id}">Arşivle</button><button class="tiny-btn" data-action="delete-resource" data-id="${r.id}">Sil</button></div></details></div></article>`}).join('')||'<div class="empty-hint">Henüz kaynak eklenmedi.</div>'}
function renderWeekly(){let s=state(),weeks=m.weeks(s.settings.start,s.settings.end);$('#planStartDate').value=s.settings.start;$('#planEndDate').value=s.settings.end;$('#planCalendar').innerHTML=weeks.map((w,i)=>{let st=m.weekStats(s,w);let start=m.fromISO(w);let days=Array.from({length:7},(_,j)=>{let d=m.addDays(w,j);return `<div class="calendar-day ${d===m.dayISO(new Date())?'today':''}"><span class="day-name">${['Pt','Sa','Ça','Pe','Cu','Ct','Pz'][j]}</span><span class="day-number">${m.fromISO(d).getDate()}</span></div>`}).join('');return `<button class="calendar-week ${selectedWeek===w?'active':''}" data-week="${w}"><div class="calendar-week-top"><div><strong class="calendar-week-title">Hafta ${i+1}</strong><span class="calendar-week-dates">${range(w)}</span></div><strong class="calendar-week-count">${st.done}/${st.total}</strong></div><div class="calendar-days">${days}</div><div class="calendar-week-bottom"><span class="calendar-week-subjects">${st.total?'Planlanan konu sayısı: '+st.total:'Plan yok'}</span><span class="calendar-week-status">${st.pct}%</span></div><span class="calendar-week-progress"><i style="width:${st.pct}%"></i></span></button>`}).join('');let w=selectedWeek,st=m.weekStats(s,w);$('#weekRange').textContent=range(w);$('#weekCount').textContent=st.total+' içerik';$('#weekProgressText').textContent=`${st.done} / ${st.total} içerik tamamlandı`;$('#weekPercent').textContent=st.pct+'%';$('#weekProgressBar').style.width=st.pct+'%';let rows=m.assignmentRows(s,w);$('#weeklyTopicList').innerHTML=rows.map(a=>`<div class="week-topic ${m.status(s,a.nodeId)==='completed'?'completed':''}"><input type="checkbox" data-complete="${a.nodeId}" ${m.status(s,a.nodeId)==='completed'?'checked':''} aria-label="Tamamla"><div class="topic-info"><strong>${esc(a.node.title)}</strong><small>${esc(a.course.name)} · ${esc(a.resource.title)}</small></div><button class="tiny-btn" data-action="move-topic" data-id="${a.nodeId}">Taşı</button><button class="tiny-btn" data-action="unassign" data-id="${a.nodeId}">Kaldır</button></div>`).join('')||'<div class="empty-state">Bu haftaya henüz konu planlanmadı.</div>';$('#weekNotes').value=m.active(s,'weeklyNotes').find(n=>n.weekStartDate===w)?.text||''}
function renderHome(){let s=state(),all=m.courses(s),allLeaves=m.resources(s).flatMap(r=>m.leaves(s,r.id)),overview=m.stats(s,allLeaves),thisWeek=m.weekStats(s,curWeek());$('#homeFocus').innerHTML=`<div class="home-focus-copy"><div class="focus-kicker">GENEL DURUM</div><h2>${overview.total?`${overview.done} konuyu tamamladın`:'Öğrenme yolculuğunu planla'}</h2><p>${overview.total?`${overview.total-overview.done} takip konusu kaldı.`:'Bir ders ve kaynak ekleyerek başlayabilirsin.'}</p></div><div class="focus-ring-wrap"><div class="focus-ring" style="--progress:${overview.pct}%"><div><strong>${overview.pct}%</strong><small>Toplam</small></div></div></div>`;let future=m.weeks(s.settings.start,s.settings.end).filter(w=>w>=curWeek()).slice(0,4);let upcoming=future.includes(curWeek())?future:[curWeek(),...future].slice(0,4);$('#homeWeeklyProgress').innerHTML=`<div class="section-head-row"><h3 class="section-title">Haftalık hedefler</h3><button class="text-link" data-page="weekly">Daha fazla</button></div><div class="home-week-progress-grid">${upcoming.map((w,i)=>{let st=m.weekStats(s,w);return `<button class="home-week-progress-card ${w===curWeek()?'current':'later'}" data-open-week="${w}"><div class="home-week-card-top"><strong>${w===curWeek()?'Bu hafta':'Sonraki hafta'}</strong><small>${range(w)}</small></div><div class="home-week-card-foot">${st.done}/${st.total} konu</div><div class="home-week-ring" style="--progress:${st.pct}%"><b>${st.pct}%</b></div></button>`}).join('')}</div>`;$('#homeCourseProgress').innerHTML=all.map(x=>{let st=m.courseStats(s,x.id);return `<div class="home-course-block"><div class="home-course-head"><strong>${esc(x.name)}</strong><span>${st.done}/${st.total} · ${st.pct}%</span></div>${m.resources(s,x.id).map(r=>{let t=m.resourceStats(s,r.id);return `<div class="home-source-row"><span class="home-source-name">${esc(r.title)}</span><span class="bar"><span style="width:${t.pct}%"></span></span><span class="home-source-count">${t.pct}%</span></div>`}).join('')}</div>`}).join('')||'<div class="home-empty-hint">Henüz ders eklenmemiş.</div>';$('#homeWeekTasks').innerHTML=m.assignmentRows(s,curWeek()).map(a=>`<div class="task-card"><div class="task-copy"><strong>${esc(a.node.title)}</strong><small>${esc(a.course.name)} · ${esc(a.resource.title)}</small></div><span class="tag ${m.status(s,a.nodeId)==='completed'?'good':''}">${m.status(s,a.nodeId)==='completed'?'Bitti':'Planlı'}</span></div>`).join('')||'<div class="empty-state">Henüz bu hafta için plan yok.</div>';renderReview()}
function renderReview(){let s=state(),r=m.activeReview(s);if(!r){$('#reviewContainer').innerHTML='';return}let arr=m.weeks(s.settings.start,s.settings.end).filter(w=>w>=curWeek());if(!arr.length)arr=[curWeek()];$('#reviewContainer').innerHTML=`<div class="section-card review-card"><div class="section-head-row"><h3 class="section-title">Geçen haftanın değerlendirmesi · ${range(r.weekStartDate)}</h3><span class="tag">${r.completedCount}/${r.plannedCount} · ${r.completionPercentage}%</span></div><p class="muted-text">Bitmemiş konular otomatik taşınmaz. İstersen seçerek yeni haftaya planlayabilirsin.</p><div class="review-options">${r.unfinishedNodeIds.map(nid=>{let n=node(nid);let res=n?resource(n.resourceId):null;return n?`<label><input type="checkbox" data-review-item="${nid}" checked> ${esc(n.title)} <span class="muted-text">${esc(courseName(res?.courseId))} / ${esc(res?.title||'')}</span></label>`:''}).join('')}</div><div class="week-actions"><select id="reviewTarget" class="small-select">${arr.map(w=>`<option value="${w}">${range(w)}</option>`).join('')}</select><button class="primary-btn" data-action="review-move" data-id="${r.id}">Seçilenleri taşı</button><button class="ghost-btn" data-action="review-unassign" data-id="${r.id}">Plansız bırak</button><button class="ghost-btn" data-action="review-defer" data-id="${r.id}">Sonra değerlendir</button></div></div>`}
function renderAnalytics(){let s=state(),cs=m.courses(s),rs=m.resources(s),nodes=rs.flatMap(r=>m.leaves(s,r.id)),st=m.stats(s,nodes),weekly=m.weekStats(s,curWeek()),planned=m.liveAssignments(s);$('#analyticsStats').innerHTML=[['Dersler',cs.length],['Kaynaklar',rs.length],['Tamamlanan konular',`${st.done}/${st.total}`],['Bu haftanın hedefi',`${weekly.pct}%`]].map(([k,v])=>`<div class="stat-card"><div class="stat-label">${k}</div><div class="stat-number">${v}</div></div>`).join('');$('#analyticsCourses').innerHTML=cs.map(x=>{let t=m.courseStats(s,x.id);return `<div class="analytics-course-block"><div class="analytics-course-title">${esc(x.name)} <small>${t.pct}%</small></div>${m.resources(s,x.id).map(r=>{let q=m.resourceStats(s,r.id);return `<div class="analytics-source-row"><span class="source-name">${esc(r.title)}</span><div class="bar"><span style="width:${q.pct}%"></span></div><span class="source-count">${q.done}/${q.total}</span></div>`}).join('')}</div>`}).join('')||'<div class="empty-state">Henüz kayıt yok.</div>';$('#analyticsPlan').innerHTML=`<div class="analytics-plan-metric"><span>Bu haftanın tamamlanma oranı</span><strong>${weekly.pct}%</strong></div><div class="analytics-plan-metric"><span>Planlanan (aktif)</span><strong>${planned.length}</strong></div><div class="analytics-plan-metric"><span>Bu hafta tamamlanmamış</span><strong>${Math.max(0,weekly.total-weekly.done)}</strong></div>`;let reviews=m.active(s,'reviews').sort((a,b)=>b.weekStartDate.localeCompare(a.weekStartDate));$('#completionChart').innerHTML=reviews.length?reviews.map(r=>`<div class="history-row"><span>${range(r.weekStartDate)}</span><div class="bar"><span style="width:${r.completionPercentage}%"></span></div><span>${r.completedCount}/${r.plannedCount}</span></div>`).join('')+'<p class="footer-note">Hafta bitiminde kaydedilmiş tarihsel sonuçlar sonradan değişmez.</p>':'<div class="history-empty">Geçmiş tamamlanmış hafta bulunmuyor. Geçmiş veriler oluşunca gerçek yüzdeler gösterilecek.</div>';$('#hoursBreakdown').innerHTML=studyData?renderStudy():`<div class="empty-state">Çalışma verileri henüz getirilmedi. <button class="tiny-btn" data-action="refresh-study">Yenile</button></div>`;
let snapshotWeeks=m.active(s,'reviews').sort((a,b)=>b.weekStartDate.localeCompare(a.weekStartDate)).slice(0,6).reverse().map(x=>x.weekStartDate);
$('#progressTimeline').innerHTML=snapshotWeeks.length?cs.map(co=>{let ress=m.resources(s,co.id);let items=ress.flatMap(r=>m.leaves(s,r.id));return `<div class="analytics-course-block"><strong>${esc(co.name)}</strong>${snapshotWeeks.map(w=>{let end=m.weekEndStamp(w),done=items.filter(n=>m.statusAt(s,n.id,end)==='completed').length;return `<div class="history-row"><span>${range(w)}</span><div class="bar"><span style="width:${percent(done,items.length)}%"></span></div><span>${percent(done,items.length)}%</span></div>`}).join('')}${ress.map(r=>{let ns=m.leaves(s,r.id);return `<div class="muted-text">${esc(r.title)}: ${snapshotWeeks.map(w=>`${labelDate(w)} %${percent(ns.filter(n=>m.statusAt(s,n.id,m.weekEndStamp(w))==='completed').length,ns.length)}`).join(' · ')}</div>`}).join('')}</div>`}).join(''):'<div class="history-empty">Gerçek ilerleme olayları biriktikçe kaynak ve ders geçmişi burada görüntülenecek.</div>'} 
function renderStudy(){let rows=studyData?.subjects||[],mappings=state().mappings;return rows.map(t=>{let mapping=mappings.find(x=>!x.deletedAt&&x.subject===t.subject),mapped=mapping&&course(mapping.courseId);return `<div class="source-line"><div><strong>${esc(t.subject)}</strong><small>${esc(mapped?.name||'Ders eşleştirilmedi')}</small></div><span>${(t.seconds/3600).toFixed(1)} saat</span></div>`}).join('')||'<div class="empty-state">Kayıtlı çalışma oturumu bulunmuyor.</div>'}
function renderSettings(){if(!c.account)return;let backups=Object.keys(localStorage).filter(x=>x.startsWith('lt_conflict_backup_'+c.account.id+'_')).sort().reverse();$('#conflictBackups').innerHTML=backups.map(k=>`<div class="source-line"><div><strong>Yerel çakışma yedeği</strong><small>${esc(k.split('_').slice(-1)[0])}</small></div><button class="tiny-btn" data-action="download-conflict" data-id="${esc(k)}">İndir</button></div>`).join('')||'<div class="muted-text">Çakışma yedeği bulunmuyor.</div>';let archive=[...m.active(state(),'courses').filter(x=>x.archivedAt).map(x=>({id:x.id,label:x.name,kind:'Ders'})),...m.active(state(),'resources').filter(x=>x.archivedAt).map(x=>({id:x.id,label:x.title,kind:'Kaynak'}))];$('#archivedItems').innerHTML=archive.map(x=>`<div class="source-line"><div><strong>${esc(x.label)}</strong><small>${x.kind}</small></div><button class="tiny-btn" data-action="restore-archive" data-id="${x.id}">Geri yükle</button></div>`).join('')||'<div class="muted-text">Arşivde öğe yok.</div>';let summary=studyData?.subjects||[];$('#mappings').innerHTML=summary.map(t=>{let current=state().mappings.find(x=>x.subject===t.subject&&!x.deletedAt);return `<div class="mapping-row"><div><strong>${esc(t.subject)}</strong></div><span class="mapping-arrow">→</span><select data-map-subject="${esc(t.subject)}"><option value="">Eşleştirme yok</option>${m.courses(state()).map(x=>`<option value="${x.id}" ${current?.courseId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`}).join('')||'<div class="empty-state">Önce çalışma sürelerini yenile.</div>'}
function openEditor(title,fields,callback){editorCallback=callback;$('#editorTitle').textContent=title;$('#editorFields').innerHTML=fields.map(f=>`<div class="field"><label for="edit-${f.key}">${esc(f.label)}</label>${f.type==='select'?`<select id="edit-${f.key}">${f.options.map(o=>`<option value="${esc(o.value)}" ${o.value===f.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea id="edit-${f.key}">${esc(f.value||'')}</textarea>`:`<input id="edit-${f.key}" ${f.type==='color'?'type="color"':f.type==='url'?'type="url"':'type="text"'} value="${esc(f.value||'')}">`}</div>`).join('');$('#editorDialog').showModal();$('#editorFields input,#editorFields select')?.focus()}
