function newResource(){if(!m.courses(state()).length){toast('Önce ders oluştur.');return newCourse()}openEditor('Yeni kaynak',[textField('title','Kaynak başlığı'),optionField('courseId','Ders',courseId||courseChoices()[0].value,courseChoices()),optionField('type','Tür','book',resourceTypes),{key:'sourceUrl',label:'Bağlantı (isteğe bağlı)',type:'url',value:''}],v=>{if(!v.title.trim())throw Error('Kaynak adı gerekli.');let newId;mutate(s=>{newId=m.add(s,'resources',{courseId:v.courseId,title:v.title.trim(),type:v.type,sourceUrl:v.sourceUrl.trim(),sourceAccess:'unavailable',importNotes:[],archivedAt:null}).id});courseId=v.courseId;resourceId=newId;go('courses');importStart(newId)})}
